{
  "regions": [
    {
      "id": "r3",
      "type": "verse",
      "lines": [
        {"n": 1, "text": "उद्यानेषु विचित्रभोजनविधिस्तीव्रातितीव्रं तपः", "end": "line"},
        {"n": 2, "text": "कौपीनावरणं सुवस्त्रममितं भिक्षाटनं मण्डनम् ।", "end": "line"},
        {"n": 3, "text": "आसन्नं मरणं च मङ्गलसमं यस्यां समुत्पद्यते", "end": "line"},
        {"n": 4, "text": "तां काशीं परिहृत्य हन्त विबुधैरन्यत्र किं स्थीयते ॥१३॥", "end": "space"}
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r4",
      "type": "commentary",
      "lines": [
        {"n": 1, "text": "यस्यां काश्याम् । तीव्रातितीव्रमत्यन्ततीव्रं तपः कृच्छ्रादि । अद्भुतभोजनप्र-", "end": "hyphen"},
        {"n": 2, "text": "कारसदृशं भवति । कौपीनस्य गुह्यस्य आवरणमाच्छादनं सुवस्त्रम् । अमितं", "end": "space"},
        {"n": 3, "text": "परिमितिरहितं भिक्षाटनं भिक्षार्थमटनं मण्डनं भूषणम । यस्यां च आसन्नं", "end": "space"},
        {"n": 4, "text": "निकटस्थितं मरणं मङ्गलसमं समुत्पद्यते । तां काशीं परिहृत्य परित्यज्य । हन्तेति", "end": "space"},
        {"n": 5, "text": "खेदे । विबुधैः सुज्ञैः किमन्यत्र स्थीयते । अत्यन्तमाश्चर्यमिदमित्यर्थः । शार्दूल०॥", "end": "space"}
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r5",
      "type": "verse",
      "lines": [
        {"n": 1, "text": "नायं ते समयो रहस्यमधुना निद्राति नाथो यदि", "end": "line"},
        {"n": 2, "text": "स्थित्वा द्रक्ष्यसि[१] कुप्यति प्रभुरिति द्वारेषु येषां वचः ।", "end": "line"},
        {"n": 3, "text": "चेतस्तानपहाय याहि भवनं देवस्य विश्वेशितु-", "end": "hyphen"},
        {"n": 4, "text": "र्निर्दौवारिकनिर्दयोक्त्यपरुषं निःसीमशर्मप्रदम् ॥ १४ ॥", "end": "space"}
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r6",
      "type": "commentary",
      "lines": [
        {"n": 1, "text": "समयो दर्शनावसरः । रहस्यमेकान्तम् । यदि स्थित्वा द्रक्ष्यसि तर्हि प्रभुः", "end": "space"},
        {"n": 2, "text": "कुप्यति इति येषां द्वारेषु वचः । हे चेतः तान् विहाय त्यक्त्वा विश्वस्य ईशितुः", "end": "space"},
        {"n": 3, "text": "देवस्य । द्वारि नियुक्तः दौवारिकः । निर्दया उक्तयः निर्दयोक्तयः । निर्गता", "end": "space"},
        {"n": 4, "text": "", "end": "space"},
        {"n": 5, "text": "दौवारिकस्य निर्दयोक्तयः यस्मात्तत् निर्दौवारिकनिर्दयोक्ति । अपरुषं निःसी-", "end": "hyphen"},
        {"n": 6, "text": "मशर्मप्रदमत्यन्तसुखदं भवनं याहि । उन्मत्तपुरुषाणां परुषवचनश्रवणस्थानानि", "end": "space"},
        {"n": 7, "text": "विहाय सर्वदातारं करुणाकरं परमेश्वरं शरणमन्विच्छेति भावः । शार्दूल० ॥", "end": "space"}
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r7",
      "type": "verse",
      "lines": [
        {"n": 1, "text": "अहौ वा हारे वा बलवति रिपौ वा सुहृदि वा", "end": "line"},
        {"n": 2, "text": "मणौ वा लोष्टे वा कुसुमशयने वा दृषदि वा ।", "end": "line"},
        {"n": 3, "text": "तृणे वा स्त्रैणे वा मम समदृशो यान्तु[२] दिवसाः", "end": "line"},
        {"n": 4, "text": "", "end": "line"},
        {"n": 5, "text": "क्वचित्पुण्यारण्ये[३] शिव शिव शिवेति प्रलपतः ॥ १५ ॥", "end": "space"}
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r8",
      "type": "commentary",
      "lines": [
        {"n": 1, "text": "अहौ सर्पे । हारे स्रजि । बलवति रिपौ समर्थशत्रौ । लोष्टे मृत्पिण्डे । कुसु-", "end": "hyphen"},
        {"n": 2, "text": "मानां पुष्पाणां शयनं शय्या तस्मिन् । दृषदि पाषाणे । स्त्रीणां समूहः स्त्रैणं", "end": "space"},
        {"n": 3, "text": "तस्मिन् । समा दृक् यस्य तस्य । क्वचित् कुत्रापि पुण्यारण्ये बदरिकाश्रमसदृश-", "end": "hyphen"},
        {"n": 4, "text": "पुण्यप्रदेशे ‘ शिव शिव शिव ’ इति प्रलपतः उच्चैर्वदतः मम दिवसा यान्तु ।", "end": "space"},
        {"n": 5, "text": "यत्र कुत्रापि देशे यस्यां कस्यामपि वृत्तौ यस्य कस्यापि संगमे सततं शिवनाम-", "end": "hyphen"},
        {"n": 6, "text": "स्मरणं कुर्वतो ममायुर्यात्विति तात्पर्यम् । शिखरिणी ॥", "end": "space"}
      ],
      "uncertain": false,
      "note": null
    },
